SELECT m.subject_id, m.hadm_id, m.admittime, m.dischtime, m.deathtime, m.admission_type, m.admit_provider_id, m.admission_location, m.discharge_location, m.insurance, m.language, m.marital_status, m.race, m.edregtime, m.edouttime, m.hospital_expire_flag, m.num_meds, AVG(m.num_meds) OVER (), PERCENTILE_CONT(0.25) WITHIN GROUP (ORDER BY m.num_meds) OVER (), PERCENTILE_CONT(0.75) WITHIN GROUP (ORDER BY m.num_meds) OVER () FROM male_inpatients_with_meds m; SELECT m.subject_id, m.hadm_id, m.admittime, m.dischtime, m.deathtime, m.admission_type, m.admit_provider_id, m.admission_location, m.discharge_location, m.insurance, m.language, m.marital_status, m.race, m.edregtime, m.edouttime, m.hospital_expire_flag, m.los, m.mortality, percentile_cont(0.75) within GROUP (ORDER BY m.los) OVER (), percentile_cont(0.25) within GROUP (ORDER BY m.los) OVER () FROM male_inpatients_with_meds_los m ORDER BY m.los DESC LIMIT 1; SELECT m.subject_id, m.hadm_id, m.admittime, m.dischtime, m.deathtime, m.admission_type, m.admit_provider_id, m.admission_location, m.discharge_location, m.insurance, m.language, m.marital_status, m.race, m.edregtime, m.edouttime, m.hospital_expire_flag, m.los, m.mortality FROM male_inpatients_with_meds_los m WHERE m.los > percentile_cont(0.75) within GROUP (ORDER BY m.los) OVER () ORDER BY m.los DESC LIMIT 1;